import {describe, it, expect} from 'vitest';
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const promptBuilder = new PromptBuilder({identity: 'Reproduction test.'});
const session = (): ChatSession => ({
  sessionId: 'repro-session',
  userId: 'repro-user',
  entries: [{role: 'user', content: 'Do something.', timestamp: '2026-01-01T00:00:00.000Z'}],
});

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'call-1', name: 'test_tool', input: {}}};

const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield* rounds[round++] ?? [];
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

const testRegistry = (): ToolRegistry => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'test_tool', description: 'A test tool.', inputSchema: {type: 'object'}},
    async () => 'result'
  );
  return registry;
};

const usageStop = (stopReason: string, usage?: UsageMetadata): MessageChunk => ({type: 'stop', stopReason, usage});

describe('Usage reporting reproduction', () => {
  it('currently under-counts by only reporting the last round', async () => {
    let reportedUsage: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reportedUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 10, outputTokens: 5, totalTokens: 15})],
        [{type: 'text', text: 'Final response.'}, usageStop('end_turn', {inputTokens: 20, outputTokens: 10, totalTokens: 30})],
      ]),
      promptBuilder,
      testRegistry(),
      {hooks}
    );

    await orchestrator.processMessage(session());

    // EXPECTATION: Sum of rounds (10+20=30, 5+10=15, 15+30=45)
    // CURRENT BEHAVIOR: Just the last round (20, 10, 30)
    expect(reportedUsage).toEqual({inputTokens: 30, outputTokens: 15, totalTokens: 45});
  });
});

